import django.db.models.expressions
from django.db import migrations, models


def clean_order_items(apps, schema_editor):
    """Rend les lignes existantes compatibles avec les contraintes ajoutées plus bas.

    - lignes dont la quantité est < 1 : supprimées (sans signification métier) ;
    - lignes en double (même commande, même article) : fusionnées en une seule
      (quantités additionnées) ;
    - sous-total recalculé = prix unitaire x quantité.
    `Order.total_amount` n'est jamais modifié : il garde le montant réellement facturé.
    """
    OrderItem = apps.get_model('api', 'OrderItem')
    OrderItem.objects.filter(quantity__lt=1).delete()

    seen = {}
    for item in OrderItem.objects.order_by('order_id', 'menu_item_id', 'id'):
        key = (item.order_id, item.menu_item_id)
        keeper = seen.get(key)
        if keeper is None:
            seen[key] = item
            continue
        keeper.quantity += item.quantity
        keeper.save(update_fields=['quantity'])
        item.delete()

    for item in OrderItem.objects.all():
        expected = item.unit_price * item.quantity
        if item.subtotal != expected:
            item.subtotal = expected
            item.save(update_fields=['subtotal'])


